368	void shm_page_dt(uintptr_t addr)
369	{
370	    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
371	    PTE *pte = find_pte(ROUNDDOWN(addr, PAGE_SIZE), pgdir);
372	
373	    if(pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)){
374	        return;
375	    }
376	
377	    /* only a page that really belongs to a share group may be detached,
378	     * otherwise a bogus address would silently unmap private memory */
379	    uintptr_t pa = get_pa(*pte);
380	    for(int i = 0; i < SHM_PAGE_NUM; i++){
381	        if(shm_page[i].count > 0 && shm_page[i].pa == pa){
382	            *pte = 0;
383	            flush_tlb_all();
384	
385	            shm_page[i].count--;
386	            if(shm_page[i].count == 0){
387	                free_user_page(pa);
388	                shm_page[i].pa = 0;
389	            }
390	            return;
391	        }
392	    }
393	}
